// prompt, i.e. --force or its --yes alias was set.
func forceRequested(cmd *cobra.Command) bool {
	force, ferr := cmd.Flags().GetBool("force")
	yes, yerr := cmd.Flags().GetBool("yes")
	return (ferr == nil && force) || (yerr == nil && yes)
