}

// runCoreClient owns the control-plane preamble shared by the active-context
// (runCore) and cluster-addressed (runCoreForCluster) variants: silence usage,
// opt into plain-HTTP token exchange if requested, build the client via
// newClient, run fn, and map API errors. The only difference between the two
// variants is which core newClient dials.
func runCoreClient(cmd *cobra.Command, newClient func(context.Context) (*coreapi.Client, error), fn func(ctx context.Context, c *coreapi.Client) error) error {
	cmd.SilenceUsage = true
	// Opt into plain-HTTP token exchange before the client (and its lazily
	// built token manager) is constructed — the manager freezes the
	// setting on first use.
	if insecureHTTPRequested(cmd) {
		auth.EnableInsecureHTTP()
	}
	client, err := newClient(cmd.Context())
	if err != nil {
		return fmt.Errorf("connect to Entire control plane: %w", err)
	}
	if err := fn(cmd.Context(), client); err != nil {
		return renderCoreError(err)
	}
	return nil
}

// markRequired marks one or more flags required, panicking if a name
// doesn't exist — that can only happen from a typo at wiring time, never
// at runtime, so a panic surfaces the bug immediately rather than letting
// a "required" flag silently not be enforced.
func markRequired(cmd *cobra.Command, names ...string) {
	for _, name := range names {
		if err := cmd.MarkFlagRequired(name); err != nil {
			panic(fmt.Sprintf("mark flag %q required: %v", name, err))
		}
	}
}

// renderCoreError converts a Core API error into the server's
// problem-detail message (so users see "organization name already taken"
// rather than ogen's decode-wrapped string), falling back to the raw error
// for transport/local failures. It returns a plain error, not a
// SilentError: main.go prints plain errors, and runCore has already set
// SilenceUsage, so the message reaches the user without a usage dump. (A
// SilentError here would be swallowed — main.go skips printing those —
// leaving e.g. a 409 conflict with no output.)
func renderCoreError(err error) error {
	if err == nil {
		return nil
	}
	if msg := coreapi.APIError(err); msg != "" {
		return errors.New(msg)
	}
	return err
}

// filterRows keeps items whose rendered cells match clause, matching on exactly
// what the table shows so the filter tracks the visible columns. clause is a
// case-insensitive substring: a bare "term" matches any column; "col=term"
// scopes the match to the column named col (a header, case-insensitive). An
// empty clause returns items unchanged; an unknown column name is an error that
// names the valid columns so a typo fails loudly instead of silently matching
// nothing. The result reuses no backing array (items[:0:0]) so it stays non-nil
// even when empty — callers encode it as JSON, where [] and null differ.
func filterRows[T any](items []T, headers []string, row func(T) []string, clause string) ([]T, error) {
	if clause == "" {
		return items, nil
	}
	col, term := "", strings.ToLower(clause)
	if k, v, ok := strings.Cut(clause, "="); ok {
		col, term = strings.ToLower(strings.TrimSpace(k)), strings.ToLower(v)
	}
	idx := -1 // -1 => match any column
	if col != "" {
		if idx = headerIndex(headers, col); idx < 0 {
			return nil, fmt.Errorf("unknown filter column %q; valid columns: %s", col, strings.ToLower(strings.Join(headers, ", ")))
		}
	}
	out := items[:0:0]
	for _, it := range items {
		if rowMatches(row(it), idx, term) {
			out = append(out, it)
		}
	}
	return out, nil
}

// rowMatches reports whether cells contain term (case-insensitive). idx < 0
// matches any cell; otherwise only the cell at idx.
func rowMatches(cells []string, idx int, term string) bool {
	if idx >= 0 {
		return strings.Contains(strings.ToLower(cellAt(cells, idx)), term)
	}
	for _, c := range cells {
		if strings.Contains(strings.ToLower(c), term) {
			return true
		}
	}
	return false
}

// sortRows orders items in place by one column's rendered value, ascending
// case-insensitive string order. spec is a header name; a leading '-' sorts
// descending. An empty spec sorts by the first column (the primary identifier),
// so a list is always deterministically ordered. An unknown column name is an
// error naming the valid columns. Stable, so rows equal on the sort column keep
// their input order.
func sortRows[T any](items []T, headers []string, row func(T) []string, spec string) error {
	desc := strings.HasPrefix(spec, "-")
	name := strings.ToLower(strings.TrimSpace(strings.TrimPrefix(spec, "-")))
	idx := 0
	if name != "" {
		if idx = headerIndex(headers, name); idx < 0 {
			return fmt.Errorf("unknown sort column %q; valid columns: %s", name, strings.ToLower(strings.Join(headers, ", ")))
		}
	}
	sort.SliceStable(items, func(a, b int) bool {
		ka := strings.ToLower(cellAt(row(items[a]), idx))
		kb := strings.ToLower(cellAt(row(items[b]), idx))
		if desc {
			return ka > kb
		}
		return ka < kb
	})
	return nil
}

// headerIndex returns the index of the column named name (case-insensitive), or
// -1 if no header matches.
func headerIndex(headers []string, name string) int {
	for i, h := range headers {
		if strings.EqualFold(h, name) {
			return i
		}
	}
	return -1
}

// cellAt returns cells[i], or "" when i is out of range — so a row with fewer
// cells than headers sorts/filters as empty rather than panicking.
func cellAt(cells []string, i int) string {
	if i >= 0 && i < len(cells) {
		return cells[i]
	}
	return ""
}

